/*
 * guide.js — the Help dialog (Help menu): a guide to each module, the methods and their limits,
 * the keyboard shortcuts (changeable: keys.js), and a search over all the help texts (these, and
 * the input and result cards of help.js).
 */

const GUIDE = [
  { tab: 14, t: 'Line', what: 'Where the app opens: the process at a glance for the inputs as they are. The flow diagram: the eight stages in their order (1 Mixing, 2 Coating, 3 Drying, 4 Peel and wind, 5 Cutting, 6 Pre heat treatment, 7 Furnace, 8 Graphene film), each with where it stands, and the streams between them, S1 to S7. The streams table: what each stage hands on -- thickness, water (as % of the GO\'s mass), solids per area, size, flatness, density. The checks table: every stage\'s checks, each with its result, its limit, how much of the limit it uses and its status, judged by the same rule as the stage\'s own page. Nothing is typed here. Nothing is solved until you ask: Solve the line (top right) solves every stage in order, each after what it needs, and the page is drawn again as each arrives; each stage page has its own Solve too.',
    uses: 'Every stage\'s inputs, each set on that stage\'s own tab (and the materials on Materials). The film and where the water leaves (top only, or top and bottom) are the stage pages\' own switches: the stages after the drying follow them.',
    read: 'Red: a defect at these settings (for example, the film still wet inside at the peel); amber: a risk (for example, water left at the oven\'s exit); green: within its limits, or solved with nothing to judge; grey: not solved yet, or not modelled yet. A check\'s bar is its result over its limit, the mark at 100 %. When the film is wet inside at the peel, only its dry part peels, and the streams after it are that part\'s. Click a unit, or a stage in the checks, to open its tab; the same states are the dots on the tabs in the bar at the top.' },
  { tab: 7, t: 'Summary', what: 'Where the app opens: every answer of the Results pages at a glance for the inputs as they are, each from the most detailed model solved (the 1D across the web, at the level of the 2D and 3D where they are solved, and saying which): the wet film and its range across the web, and a card each for the contact line (does slurry reach the dry edge?), the web edge (does it scallop before the oven?) and the film surface (do streaks survive to the oven?), with a small chart and the verdict of that page.',
    uses: 'Every shared input, through the pages it summarises. The inputs bar is hidden here at first: Inputs in the tab bar (or Edit inputs) shows it, and the cards follow every change.',
    read: 'Each card\'s badge answers its question (No in green, Yes in red, a caution in amber) with the key number under it; click a card for its page and the full detail. The line under the cards is the thin-film validity check (the 1D is a lubrication model). Go further leads to the CFD, the DOE and the measured data.' },
  { tab: 12, t: 'The stages', what: 'Each stage of the process is a tab of its own, in the process\'s order: 1 Mixing, then after 2 Coating: 3 Drying, 4 Peel and wind, 5 Cutting, 6 Pre heat treatment, 7 Furnace and 8 Graphene film, each with a dot for where it stands; the coating\'s wet and dry film and its flakes are under Coating › Results. Drying, Peel and wind and Furnace go in three steps: Setup (their inputs, the same values as in the inputs bar), Solve (where it stands, the solver\'s settings and checks) and Results (the answer in a line, the warnings folded; on Drying, Peel and wind, Cutting, Pre heat treatment, Furnace and Graphene film, and their 1D, 2D and 3D, the results listed on the left, the one picked shown large, the key values beside it); Cutting in two, Setup and Results (it solves by itself after the film); Pre heat treatment in two, Setup and Results; Drying, Pre heat treatment and Furnace also have Coating\'s sub tabs 1D, 2D and 3D beside their Results: each a page of its multiphysics (the drying film\'s heat, water, the oven\'s air through the web and its stress; the stack\'s heat, water and stress; the furnace\'s heat, chemistry, gas and stress, solved together) in Coating\'s four steps, Geometry (the domain to scale, its parts and their materials), Mesh (the mesh drawn, its numbers, its elements and time steps editable), Solve (the equations, the faces and their conditions, the time, the solver; Solve) and Results; the Graphene film shows the furnace\'s results for the film that comes out. Mixing: the slurry as its card on Materials says (the mixer itself is not modelled yet). Coating › Results › Wet and dry film: a mass balance on the wet film the flow gives: the dry film\'s thickness, the coat weight dry and wet, the water the oven must take out (per m², and per hour over the web at the line speed) and the time in the oven. Drying: the line drawn with its zones (what is above the film in each, pictured) and the film in it, the water leaving from the top only and from the top and the bottom side by side (each explained by its picture), where a skin forms and where the film is dry, water left at the exit, the temperatures, the evaporation, the film and its skin along the line, and through the film at the place you click; a table for every location and the web; your oven temperatures and exit measurements over the computed. Peel and wind, the film peeled off: each film followed on through the room to where it is peeled by hand and wound on the winder\'s roll (its top out); six checks, each with its picture (cracks, the peel force, tears or bits left, the curl, the roll, blisters or wrinkles), for both ways the water leaves; the stress at its top along the line, the crack risk, the peel force at every angle from 0 to 180° (the winder\'s angle is not known), the stress through the film at the peel, the blister risk, and a peeled sheet drawn curled on a table; a table for every location; your curl, cracks and peel force, with the film\'s values they imply and Use to put them on the Film card. Cutting: a piece cut from the roll in 3D (30 × 30 cm unless you change it): as cut, held up and lying on a table under its weight, which way it rolls, how high its corners and edges lift; its size pressed flat after the pre heat treatment (dried through) against as cut. Pre heat treatment: the pieces in the pressed stack: their water across a piece through the pre heat treatment and after it under the plate in the room, when the middle is dry, the pull each holds flat against the film\'s strength, the water they take back, their size out of the stack and a day later; the piece let go out of the stack and a day later (a switch over the drawings: as cut, out of the stack, a day later), held up and on a table, with its heights and its waves; your measured sizes (before the pre heat treatment, after it, after the furnace), after the oven read back as the swelling it implies at the water the stack gives it then. Furnace, and Graphene film: the pieces one between each two graphite papers in the graphite holder, through the two runs in argon (to about 1000 °C, then to 2800 °C); five checks as lights, each with its picture, when and where (puffing up; cracks; waves; sticking to its papers; an even thickness against your limit), green below 80 % of its limit, amber to 100 %, red past it, each at the stack\'s worst piece; the stack\'s top, middle and bottom pieces side by side (the weight on each, its thickness and spread, its pull and squeeze, when it sticks) and one of them shown in the key values, charts and map; the batch\'s thickness and spread (each piece\'s own and the pieces\' about the stack\'s, and the stacks\' when the load\'s temperature spread is given); its size after the furnace, free and as held on its paper; the graphene film\'s thickness, density, heat along it, C/O, the weight kept and how far it graphitized; the runs, the weight, the C/O, the thickness at the middle and near the edge and the gas in a piece against its layers\' hold through both runs, its pull and squeeze along itself against what they take (and where it sticks), and the graphene film\'s thickness across the piece; your measured thickness, weight kept and heat conduction beside the computed, with Fit and Use to put what they imply on the Furnace card.',
    uses: 'The wet film from the flow (the 1D at every position across the web, and at the four locations the 2D or 3D where solved for the inputs as they are), the slurry\'s card on Materials (solids fraction, GO and water densities, the dry film\'s packing), the web speed, and the oven\'s zones in the inputs bar (their lengths set the time in the oven). The film peeled off also uses the Film card on Materials and, in the inputs bar under the oven\'s zones, After the oven: the stretch from the oven\'s exit to the peel and the winder\'s core; the pieces\' size, the pre heat treatment\'s temperature, the time in it and the time under the plate after it (from you). The furnace uses the Furnace card on Materials, the GO\'s C/O (the slurry card) and, in the inputs bar, The furnace: the two runs\' programs (steps, or the cycle from your file), the pieces in a stack, the graphite paper\'s thickness and how much bigger it is, the plate resting on the stack, a gap above it or the holder\'s next plate on it, the load\'s temperature spread (not known until you give it), and your limit on the thickness\'s spread over a batch.',
    read: 'The stages are tabs in the bar at the top, their dots saying where each stands: click one, or move along the bar with the arrow keys; a stage\'s steps are under its name. Change an input in Setup or in the inputs bar: they are the same. The furnace\'s runs, one at a time: type in the table or drag a corner of the drawing beside it (where a ramp ends, a hold ends, the cooling ends). The piece: Map from above, coloured; 3D turned by dragging. Mixing\'s Edit in Materials opens the slurry\'s card; the coating\'s 1D, 2D and 3D are on Coating. The tiles give the web\'s mean; the chart the wet film (dashed) and the dry film across the web; the table each location with the model its film is from. Dry film = wet film × solids fraction / packing: the solids stay, the water leaves. The film peeled off: 1× and above on the crack and blister risks, they form; the peel force per width is the force over the strip\'s width.' },
  { tab: 13, t: 'Materials', what: 'The cards of what the line is made from. The slurry: GO solids in water, each value with its unit, its definition method and its data source, edited here; what follows from it (the slurry\'s density, the solids by mass, the dry film\'s density). How the slurry flows: the rheology model (chosen here or in Coating › 2D), the inputs bar\'s viscosity, n, yield stress and surface tension as they are, and edited here the Carreau–Yasuda and Cross laws\' extras and the structure (thixotropy: on or off, its rebuild time, the shear rate that halves it, its yield and viscosity gains). Rheometer tests: exports from the rheometer imported, plotted and fitted. Flakes: how they line up (on or off; the liquid crystal, Doi–Hess, by default, or the suspension, Folgar–Tucker; their values and how finely it is computed). Drying: how the film dries in the oven (the flakes\' collective diffusion, water vapour through the skin, GO\'s heat values, the film\'s emissivity and the IR it takes, the water the dry GO keeps -- its sorption isotherm -- and the room between the blade and the oven). Film: the dry film\'s stiffness, strength and fracture energy, how it shrinks as its water leaves, how it splits between its layers, its hold on the fibre web, the web\'s stiffness and heat expansion, and the wet film under a skin, how water moves along the pieces in the pressed stack and how fast the wet film creeps there; the measured curl, cracks and peel force on Process give them. Furnace: the GO\'s chemistry as it heats (its hydrogen, each stage\'s share of its oxygen, where it leaves and its spread, the gas it leaves as), its layers ordering into graphite (their spacing going in, the crystallites\' size, graphite\'s heat conduction and the size that halves it), the gas through the film and what holds its layers, and the graphite paper; the graphene film\'s measured thickness and heat conduction on Process give two. The fibre web it is coated onto, as set in Coating › 2D (its test report and the 2D setup\'s fibre values).',
    uses: 'The slurry and rheology cards are their own (the rheology card shows the inputs bar\'s slurry inputs as they are); the rheometer tests their files; the fibre web card the fibre thickness and the 2D setup\'s fibre.',
    read: 'Change a value in the slurry card and everything that uses it follows: its density goes into the 1D, 2D and 3D flow (gravity and inertia), and the solids and packing into the Process tab\'s mass balance. Set a value\'s flag to Measured and its source once you have measured it. Edit in the inputs / Edit in Coating › 2D open where the other cards\' values are set. Rheometer tests: Import rheometer file reads a flow curve, a thixotropy test (3ITT), an amplitude or a frequency sweep; each law or the structure is fitted, its values with one standard error (loose: the test does not pin it down); Use this fit puts them on the card (Measured, the file as the source). Fit the flow curve first: the thixotropy fit keeps the steady law as set.' },
  { tab: 1, t: 'Contact line', what: 'Where the meniscus leaves the blade: the cross-section at the web centre (a schematic of the exit face at its angle, with the solved film and contact line), and the contact line\'s height up the exit face at every position across the web, from the most detailed model solved (answers across the web: the 1D, at the level of the 2D and 3D where solved).',
    uses: 'Process (not the oven), Slurry, Blade and bead, Variation across the web (waviness, fibre thickness and wetting variation move the line up and down).',
    read: 'Left: blade, slurry, meniscus and film at the centre. Right: the contact line up the face (mm) against position across the web; the red dashed line is the notch corner, where slurry reaches the dry edge. The pills say whether it stays pinned, is uneven, or reaches the corner.' },
  { tab: 2, t: 'Web edge', what: 'The wet edge as a ridge of slurry that surface tension pulls into beads (Rayleigh–Plateau), slowed by viscosity and frozen by a large enough yield stress: its scallop amplitude from the blade to the oven. The ridge is as high as the wet film at the web\'s edge (the solved answer across the web; of the two edges, the one with the larger scallops at the oven).',
    uses: 'Process (speed, gap, oven distance), Slurry, Blade and bead (through the film thickness, solved), Edge irregularity at exit.',
    read: 'Top: scallop amplitude against distance from the blade, with the "visible" line at 0.2 mm. Bottom: the edge seen from above at the oven. An order-of-magnitude indicator: which lever matters, not exact millimetres.' },
  { tab: 3, t: 'Film surface', what: 'Streaks and ripple on the film surface: the ripple the blade leaves (gap waviness through dh/dH, plus vibration), and how surface tension levels it before the oven; a yield stress leaves a residual. The 1D\'s levelling on the solved wet film (the most detailed model solved there), at the location where the most is left at the oven.',
    uses: 'Process, Slurry, Blade and bead, Blade gap waviness, Ripple wavelength, Vibration ripple.',
    read: 'Top: the surface across the web just after the blade (dashed) and at the oven (solid), in µm. Bottom: ripple amplitude against time, with the oven marked. The pills say whether the ripple survives to the oven.' },
  { tab: 8, t: 'Gap flow (1D)', what: 'The first stage of Flow: the slurry\'s flow along the blade in 1D lubrication, solved exactly across the gap at every station for the rheology model (a yield stress leaves an unsheared plug), with the 2D\'s blade shape, exit face, fibre slip and locations. The bead pressure at the inlet, falling to ambient at the metering edge, sets the flow rate q; the film left on the web is q / U.',
    uses: 'Process, Slurry, Blade and bead, each location\'s gap and contact angle (Variation across the web or its own values), and the 2D setup: blade entry, exit face, rheology model, fibre.',
    read: 'The switch at the top picks the location. Pressure along the blade, with the 2D\'s along the web when that location is solved (the 2D\'s meniscus sets its pressure at the edge, the 1D takes ambient); the gap; the shear stress on the web and the blade; velocity across the gap at the inlet, midway and the edge. The table compares the 1D, the 2D and (later) the 3D at the four locations.' },
  { tab: 10, t: 'To the oven (1D)', what: 'The film from the metering edge to the oven: the 1D thin-film equation (the web dragging the film, surface tension, gravity) from the full gap at the edge, with the flow rate of the 1D gap flow, settling to q / U; and the ripple on it levelling on the way.',
    uses: 'As the gap flow, plus the ripple\'s sources: blade gap waviness, vibration ripple, ripple wavelength; and the distance to the oven.',
    read: 'Top: the film height against the distance from the edge, with q / U dashed. Bottom: the ripple amplitude from the blade to the oven. The pills say whether the ripple survives to the oven.' },
  { tab: 11, t: 'Across the web (1D)', what: 'The 1D gap flow at 61 positions across the web, each with its own gap (blade waviness, fibre thickness variation) and contact angle (wetting variation): the wet film and the contact line against position.',
    uses: 'As the gap flow with the shared values (a location\'s own values do not apply here), plus the notch face length for the dry-edge line.',
    read: 'Left: the wet film across the web; the dots are the 2D at its four locations when solved. Right: the contact line up the exit face from the static meniscus; past the dashed line the slurry reaches the dry edge.' },
  { tab: 0, t: 'Start-up', what: 'An animated cross-section of the slurry metered under the fixed blade onto the moving fibre, from start-up: the pool fills and pulses with the feed, the fibre accelerates, the film forms and the downstream surface is solved live. A second pane magnifies the meniscus on the same clock.',
    uses: 'Process (not the distance to the oven), Slurry, Blade and bead; the across-web inputs through the position slider (the local gap and wetting there); the scenario in the inputs bar (feed pulsing, pool, position, playback speed).',
    read: 'Play / Pause and the time slider drive both panes. The pills give the contact line\'s place (at the edge, up the face, or at the notch corner: the dry edge gets wet) and the local gap and contact angle; the results strip gives the gap, wet film and shear rate at that position. A red pill or "surface solve stopped" means the numbers there are not to be trusted.',
    more: 'How it runs: the fibre starts at rest under a pool of slurry already deeper than the gap, starts at 3 s and reaches full speed 1.5 s later. The nozzle at the pool surface feeds in pulses, on average what leaves through the gap; the pool level comes from that volume balance, and the gap flow from the fibre speed and the bead pressure, taken as proportional to pool depth. The blade diameter is 100 mm; the notch size, pool depth and length are fixed values. Bead height scales with bead pressure for display.' },
  { tab: 4, t: '2D CFD', what: '2D Navier–Stokes flow under the blade, over its exit face and into the free film, with the meniscus and its contact line solved together with the flow, at four positions across the web. Velocity, pressure, shear, viscosity and more, post-processed from the stored solutions.',
    uses: 'Process, Slurry, Blade and bead, Variation across the web (each location\'s local gap and contact angle), and the CFD setup in the inputs bar (blade entry, exit face, rheology model, fibre, air, solver and mesh, locations with their own inputs).',
    read: 'The page is in four steps (the bar beside 1D | 2D | 3D, each with where it stands). Geometry: the blade drawn to scale with its dimensions (drag a round handle, or click a value and type; the gap and contact angle of each location beside it). Mesh: nothing is meshed until you press Mesh; then the mesh the solve starts on (or, once solved, the solved one). Solve needs it, and after an input change it is out of date until you press Mesh again, shaded by each element\'s shape quality, with its numbers (elements, nodes, worst and mean quality, a histogram, aspect ratio, shortest edge; "show" zooms to the worst element); the mesh study is there too. Refinement zones (beside the mesh) make elements smaller where you ask: tick the metering edge, the contact line, the exit face or the film and give an element size, add layers at the web or at the blade and surface (how many, the first one\'s thickness, their growth), or add bands along the flow and drag their ends on the drawing. The mesh stays structured, so a band covers the gap\'s full height and a layer runs the full length; the note under them says about how much longer a solve takes. Mesh to an accuracy (its bottom tab, or the toolbar) solves a location (or all four), refines the mesh and solves again until the wet film and the contact line change less than a target from one mesh to the next: adaptively (each element\'s error estimated from its velocity gradients against smoothed ones, and the columns and rows carrying most of it split) or everywhere (every count ×1.25, with Richardson extrapolation of the error left). Use this mesh keeps the last mesh as the location\'s own (Adapted) with its solution. Solve: the boundary conditions drawn on the domain (click a blue value to change it) and the solver settings; Run (Ctrl+Enter from any step) solves the four locations and opens Results when they are done. Results: the flow. Run solves the four locations (each in its own worker); while they solve, a bar each shows about how far it has got (≈: an estimate from the solves done and how far the current one\'s residual has fallen toward the tolerance; the status bar shows them together on every page) and what it is doing. The toolbar picks the location (or Compare, or Difference), the field, streamlines, vectors, contours; the zoom bar on the plot zooms and pans (wheel, drag). Click the colour bar for its scale. The bottom panel has flow metrics, probes, cut lines, across-web and profile charts, the flakes\' alignment (Flakes: their flatness through the film leaving the blade and at the oven, the two SEM cuts with the measured angles over them, cross-sections drawn from the flakes, a table by streamline; Redo alignment after changing its values; SEM images read automatically or by hand, and tables of angles), fibre results, convergence, the mesh study, saved cases, problems, messages, history and the method. "Out of date" marks results whose inputs changed since they were solved.' },
  { tab: 9, t: '3D', what: 'The flow in 3D on a strip across the web around one location. The blade is made from the 2D setup (its side profile extended across the web, the gap varying there as the inputs say) or read from an STL or STEP file of the blade and placed with its lowest point at the gap. Solve 3D first solves each station across the strip in 2D at its own gap and contact angle, then couples them in a 3D Navier–Stokes solve with the meniscus and its contact line, so the flow across the web, which the 1D and 2D cannot have, is in it. The full web width is solved as overlapping strips in parallel, each with its neighbours\' latest solution on its sides, sweep after sweep until they agree (minutes; the same answer as solving the whole width at once, which would not fit in a browser\'s memory).',
    uses: 'Everything the 2D uses at that location (blade, rheology, fibre and web slip, bead pressure, surface tension, the gap and contact angle with their variation across the web), the 3D geometry (from the 2D setup, or a file: its units, axes and inlet distance; the exit-face angle from the 2D setup), the region and the 3D mesh in the inputs bar.',
    read: 'The page is in four steps, as 2D: Geometry (the blade in 3D, the region), Mesh (the hexahedral mesh with its size, unknowns, memory and time, and its shape quality: before solving, each station\'s starting layout; once solved, the solved hexahedra\'s; refinement zones: the 2D\'s along the flow and up the gap, at every station, and across the web the region\'s ends or bands; mesh to an accuracy: the 3D solved on finer and finer meshes, adaptively or everywhere, until the film and contact line stop changing, the last kept with Use this mesh), Solve (the boundary conditions, the sides of the strip or the web\'s edges, and Solve 3D) and Results (the flow). Solve 3D (Ctrl+Enter from any step) runs in the background and opens Results when it is done; Esc stops it; the mesh settings show about how large and long a solve is. While it solves, one bar shows about how far the whole solve has got (≈: the stations\' 2D and the 3D, or the full width\'s sweeps, weighted by their estimated times, and how far each Newton solve\'s residual has fallen) and one more for each station or strip being solved; the status bar shows it on every page. The view colours the flow by a field (speed, pressure, shear rate, viscosity, velocity across the web) on its outer faces: the strip\'s two sides are cuts through the flow; turn the blade off to see the top. Streamlines (after a solve): tubes from the inlet, spaced by equal flow up the gap, coloured along their length by the same field; Low / Medium / High sets how many; the slurry\'s faces turn faint while they show. Drag to turn, wheel to zoom, right-drag to pan. The charts: the film and the contact line across the strip (3D against each station\'s own 2D), the pressure on the blade\'s underside, the pressure along the blade at the middle. The table\'s 3D column is the strip\'s middle, or the full width\'s station nearest each location. Full width: its stations sample the variation across the web at their spacing; the web\'s edges are symmetry planes (with a skewed blade: open, each held at its own station\'s flow along the blade; the edge bead is not modelled either way). "Out of date" marks a result whose inputs changed since.' },
  { tab: 5, t: 'DOE', what: 'A full-factorial design of experiments: 1–3 factors at 2–5 levels each, every combination solved, several at a time. Coating DOE: at one location, the factors process, slurry, blade geometry and mesh, each run a 2D CFD. Furnace DOE: the furnace\'s runs for the film\'s piece as it is, the factors its heating rates, run 2\'s top and hold, the stack in its holder (pieces, the plate, the gap, the paper) and eight of the Furnace card\'s values; its outputs the graphene film\'s and the lights\'. Each keeps its own design and runs.',
    uses: 'Coating DOE: the CFD base case of the chosen location (every input as in 2D CFD). Furnace DOE: the furnace as set on Process (its base case). Both: the factors in the Design tab.',
    read: 'Response: an output against one factor, a line per level of the second, a panel per level of the third. Response map: two factors as a coloured grid. Main effects: the mean output at each level of each factor, so the steepest line is the strongest lever. Runs lists every run; failed runs say why.' },
  { tab: 6, t: 'Measured data', what: 'Measurements from a CSV (wet film or coat weight across the web or against settings, the contact line, the meniscus shape, the edge amplitude, the surface ripple) compared with the model and the CFD; a fit adjusts inputs to match them.',
    uses: 'Every input (the predictions use the solved answers, the 1D and the CFD), and the datasets imported.',
    read: 'The parity plot puts each point at (measured, predicted): on the 1:1 line is a perfect prediction, inside the dashed lines within ±10 %. The Comparison tab lists each point with the % errors and their RMS; Solve in CFD adds the CFD column. The Fit tab adjusts 1–3 inputs to the chosen datasets and shows the error before and after; Apply sets them.' },
];
// (WF-2: the guides in the tab bar's order -- the Line, Materials, the stages, the coating's pages, Results, Studies)
const GUIDE_ORDER = [14, 13, 12, 8, 10, 11, 0, 4, 9, 1, 2, 3, 7, 5, 6];
GUIDE.sort((a, b) => GUIDE_ORDER.indexOf(a.tab) - GUIDE_ORDER.indexOf(b.tab));

const METHODS = [
  { t: 'Inputs and their data', d: 'From your measurements: web speed, machine height, fibre thickness, viscosity 10.5 Pa·s at 2.7 1/s, and the design wet film of 1.45 mm: the default bead pressure (0.49 kPa) is back-calculated so the 2D CFD gives 1.45 mm at L1 (it is not itself a measurement). The others -- surface tension (0.07 N/m), the contact angle on the blade, yield stress, shear-thinning index, land length, notch face length, and on Materials the density of the GO solids, the packing of the dry film and the like -- are set on the inputs bar and Materials, each with its data source (the slurry\'s density follows from its solids: 1360 kg/m³ at 40 vol% GO of 1.9 g/cm³). Measured data fits them to your measurements.', lim: '' },
  { t: 'Solving on request', d: 'Nothing solves by itself: opening the app or a page, or changing an input, never starts a solve. Each model has a Solve button beside its state (Not solved, Solving, Solved, Out of date); a model asked for solves first what it needs (the drying the 1D, the film the drying, and so on), and Solve the line solves the whole line in order. When an input change leaves solved results out of date, a bar lists them: Re-solve solves the ones ticked, Keep as is leaves them (marked out of date where they are shown) until the next change, when it asks again. The report asks too, before it is made, about models it shows that are not solved.' },
  { t: 'One answer per quantity', d: 'Each quantity the pages show (the wet film, the flow rate, the contact line up the exit face) comes from the most detailed model solved for the inputs as they are, and says which: at a location the 3D (a strip there, or the full width), else the 2D CFD, else the 1D -- the 3D only with the structure (thixotropy) model off: the 3D has the plain flow curve, so with the structure on every location takes the 2D (models are not mixed) and the 3D page labels its numbers “plain flow curve”; across the web the 1D\'s profile (61 positions) scaled at each position to the more detailed models where they are solved (their ratio to the 1D there, interpolated between the locations and held beyond them). Results, Process and its chain, the report and Measured data all use it; the 1D / 2D / 3D table on Coating › 1D compares them.',
    lim: 'Between the locations the scaling is an interpolation: the 1D\'s shape across the web at the 2D\'s level. The 1D is a lubrication model (valid while the thin-film checks hold: Reynolds number below 1, capillary number below 0.1, gap / land length below 0.2); its meniscus on the exit face is static (no dynamic wetting).' },
  { t: 'Variation across the web', d: 'The local gap is the machine height less the fibre thickness, plus the blade waviness (a sine of the chosen wavelength), the blade\'s tilt (the gap difference from one web edge to the other, centred on the middle) and the fibre thickness variation; a skewed blade (its edge at an angle to the cross direction) moves slurry across the web in the 3D, the pressure under it pushing the slurry at right angles to the blade; the local contact angle varies by the wetting variation.',
    lim: 'The fibre-thickness and wetting variation follow a fixed smooth pattern: a stand-in for real scatter, not a measurement of it.' },
  { t: 'Web edge beads', d: 'Rayleigh–Plateau growth of the edge ridge (radius half the film): growth rate γ/(6 μ R), wavelength 9 R, with the viscosity at a slow 0.1 1/s; a yield stress larger than the Laplace pressure γ/R freezes it. Grows from the edge irregularity at exit until it saturates at a quarter wavelength.',
    lim: 'An order-of-magnitude indicator.' },
  { t: 'Flake alignment', d: 'The flakes\' normals p as an ensemble (1000 by default) on each of 24 streamlines that carry the film\'s flow, traced back to where the slurry enters the 2D and carried forward through its velocity gradient: dp/dt = W·p + β (D·p − (p·D·p) p) (Jeffery, β from the flakes\' thickness / width), with rotary diffusion (Folgar–Tucker: C_i × the shear rate; Doi–Hess: D_r) and, for the liquid crystal, the flakes lining up with each other (Doi–Hess\' mean field, strength U). They start steady in the flow where they enter; where the liquid crystal keeps turning over there (a slow shear), as all moments of its turn mixed. After the domain the film rests on the web until the oven. Flatness = (3⟨p_y²⟩ − 1) / 2; an SEM cut shows each flake as a line at an angle to the web.',
    lim: 'Checked against exact results (Jeffery\'s orbit, rotary diffusion, planar extension, a Fokker–Planck solution in shear, Maier–Saupe at rest) and converged in the flakes\' number and the step. The values U, D_r and C_i are fitted to measured alignment; a real liquid crystal also has elasticity between neighbouring directions (textures, defects) that this model leaves out; the model\'s depths are the wet film\'s (the dried film shrinks alike). Dried: as the film dries it collapses through its thickness to φ0 / φ_m of it (it cannot shrink along the web), which flattens every flake alike (tan θ\' = λ tan θ in a cut); the SEM cuts are compared dried.' },
  { t: 'Drying in the oven', d: 'Each film (a location\'s, and the web\'s mean) as a strip on its web from the blade through the room and the oven\'s zones at the line speed, 1D through its thickness. The water moves against the flakes by their collective diffusion (Routh–Russel for hard spheres, a thin disc\'s Brownian diffusion, × the card\'s factor) in the GO\'s own coordinate; where the solids reach the dry film\'s packing at a surface a skin forms, and the water then leaves as vapour through it (a GO laminate\'s permeability); the dry GO keeps its sorption water (GAB) at the last zone\'s humidity. Heat: the air blown up through the fibre (it leaves at the film\'s bottom temperature), above the film the oven\'s still air (natural convection with the vapour\'s buoyancy), slot-nozzle jets (Martin) or IR, and the walls\' radiation; evaporation (Stefan diffusion) takes its heat where the water leaves. Water leaving from the top only and from the top and the bottom are both computed.',
    lim: 'Checked against the steam tables (IAPWS-IF97), the wet-bulb temperature against adiabatic saturation, the exact series solution for constant diffusivity, the skin front\'s own ODE, the low-Peclet limit, water and energy conserved, the grid and time step converged, top and bottom symmetric (drying.validate.js). Of its values, the skin\'s permeability and the flakes\' diffusion decide the most; compare with your oven temperatures and the film at the exit. Not in: the edges of the web (1D through the thickness), vapour bubbles once the water boils under the skin (flagged: blisters), the air\'s humidity rising along the oven.' },
  { t: 'The film, peeled off', d: 'Each film\'s drying is followed on through the room after the oven to the peel, with its history kept. A layer of the film sets when a skin\'s front passes it and carries stress from then on: its natural length follows its water (the swelling β per kg of water per kg of GO) and its temperature, its stiffness softens with water, and water keeps moving through the set layers (by the vapour through the laminate). A skin over wet film floats on the paste (too soft to hold it) and joins the film on the web when the fronts meet. The layers stuck to the web share its stretch; the web expands with the heat. Cracks: a 2D plane-strain finite-element model of the layers (9-node elements) gives the energy a crack through the film frees, against the film\'s fracture energy; their spacing from where a new crack midway between two others no longer frees enough. The peel: the force per width where a steady peel frees the film\'s hold on the web (Kendall, with the film\'s stretch and the stress it stores), at every angle; it tears if the pull and the bend at the peel front beat its strength. Curl: the free film\'s layers\' lengths (right after peeling, and settled with the room\'s air); the roll: bent round the core, its top out. Blisters: a patch squeezed on the web buckling off it against its hold.',
    lim: 'Checked against Stoney\'s and Timoshenko\'s bilayer bending, the channel crack\'s energy on a matched substrate (Beuth) and a buried crack (π/4), the finite-element patch test and mesh convergence, Kendall\'s peel and the pre-strained lap, the elastica, Crank\'s series for the water moving, layers set free of stress, the forces balancing, and the curl linear in β (film.validate.js). Of its values, the swelling with water, the fracture energy and the hold on the web decide the most: measure the curl, the crack spacing and the peel force. Not in: the sheet\'s corners (the 3D sheet comes later), creep while wound beyond the share set on the card, the web\'s own weave, the film sliding at the peel.' },
  { t: 'The pieces in the pressed stack', d: 'The pieces stacked 20 at a time under a plate, each held flat but free in its plane (friction under a light plate is far below the drying\'s pull). Their water moves along them to the stack\'s edges (press.js): ρ ∂X/∂t = ∇·(K p_sat ∇a), the activity a from the sorption isotherm (GAB: GO\'s own water between its layers, its C at the temperature -- warm GO holds less), the edges at the air\'s -- the pre heat treatment\'s (the room\'s air heated), then under the plate the room\'s. A quarter of a piece with its mirror lines, cell-centred finite volumes graded to the edges; Crank–Nicolson after four implicit Euler steps, Newton on the activity (an exact, symmetric Jacobian). Held flat, each piece\'s stretch alone (the plate\'s stretch solved at once), its natural stretch and stiffness its water\'s (the film\'s layers at that water); each point a Maxwell body that creeps at a rate going as its water (wet GO creeps, dry does not), the curl eased alike; the creep only in the pre heat treatment. Let go (the plate\'s energy): its natural stretch and curl as fields -- its water then and the creep the stack left -- raised in steps from flat, a small seeded disturbance to leave the flat saddle and a fresh one when it settles on a saddle; shapes even about both middle lines.', lim: 'The stack\'s permeability and the creep time are not measured: the first fits your answers (dry all over out of the oven, the size back 1–2 h later, the same a day later), the second is set from your photos of the waves. A thin piece has many shapes of about the same energy: the one shown is the one reached let go gradually. The pieces lie flat and alike in the stack (the top and bottom ones, against the plate and the tray, as the rest).' },
  { t: 'The drying\'s multiphysics (MP-5)', d: 'The wet film drying on its fibre web through the room and the oven, in 1D (at one place, the web resolved), 2D (a section across the web\'s full width, the wet film as thick as the coating leaves it at each place) or 3D (a piece of the line across the web, each point at its own place on the line), its heat, its water, the oven\'s air through the web and its stress solved together (drying-mp.js). The water at each place is drying.js\'s, the same code: in the GO\'s own coordinate ζ, the flakes\' collective diffusion, a skin where the solids reach the dry packing, the water leaving through it as vapour into the air above (and below, where it leaves both ways), on a grid clustered at the wet film\'s fronts; along the film the flakes\' diffusion moves a share D t / Δy² of the water (shown, about 10⁻⁵), so the places are not coupled through their water. The heat through the web and the film and along them (implicit Euler, the vertex-centred finite volumes of linear elements; through the film its conductance k / (dz/dζ), along it k dz/dζ, the flakes flat: in series through, side by side along; the web its fibres in the air by Maxwell–Eucken), the evaporation\'s latent heat where the water leaves (the surface, or a skin\'s front inside the film), the air through the web carrying heat (the fluxes exponentially fitted: exact for steady flow along a link). The air through the web (2D, 3D) by Darcy, solved each step: the plenum under a zone at the pressure that drives its air speed through the bare web, the bare web\'s top and the web\'s edges open, the wet film sealed. Water and heat each step in turn until they agree (10⁻⁴ K). The stress (film.js\'s rule): a layer sets stress free when a skin\'s front passes it, then shrinks and swells with its water (its isotherm\'s, film.js) and temperature; the wet film under a skin a gel; the web with its temperature; held flat. 1D: film.js\'s laminate (a skin over the wet film free on it); 2D: plane-strain elements across the web, free along the line with no net force (generalized plane strain: the film is continuous along the line, so a skin over the wet film is held along it); 3D: the piece\'s elements, its ends at a common strain with no net force. Checked (drying-mp.validate.js): the 1D against drying.js (the water at the exit within 0.2 %, the temperatures along the line within 0.3 K, the skin where drying.js has it), heat through the film against the series resistances (0.001 K), the air through the bare web against the exact exponential profile, Darcy under a sealed film against the exact series (1.6 %), the 2D with an even film = the 1D (10⁻¹⁰), the 3D at one place = the 2D (10⁻⁹), the section\'s stress held flat against the laminate (0.3 %), its force across nothing at every place (free edges), the bonded layers against film.js (5 %), the mesh converged, the water conserved exactly and the energy within 0.2 %.', lim: 'The plenum\'s pressure is the one that drives the zone\'s air speed through the bare web: with the wet film sealing the web it hardly passes under the film (the 2D shows where it goes). The plenum\'s side of the web\'s underside has natural convection only. The film\'s side faces at its ends exchange heat but dry no further in than a skin grows (a fraction of a millimetre, below the mesh across). The air in the web at the plenum\'s temperature\'s density; local thermal equilibrium between the air and the fibres.' },
  { t: 'The stack\'s multiphysics (MP-1)', d: 'The pressed stack\'s heat, water and stress solved together (stack-mp.js on mp-core.js, the multiphysics core every stage is to share). Heat and water in one system at every node, the temperature T and the vapour\'s pressure p (Künzel\'s formulation, vapour only): the water a piece holds S = ρS X, X GO\'s own water from the sorption isotherm (GAB) at the local temperature (its C at T); ∂(ρc T − L S)/∂t = ∇·(k ∇T) and ∂S/∂t = ∇·(K_v ∇p) -- drying takes its latent heat where the water leaves. The vapour moves along the pieces at the Film card\'s stack permeability (the Results step\'s) and through them at the Drying card\'s skin permeability; the plate is aluminium; the pieces conduct along and through at the Drying card\'s two values. The faces: the oven\'s air by natural convection from the correlations (the plate\'s top facing up, the underside facing down, the sides vertical: Churchill–Chu) or a fan\'s along the plate, radiation to the walls at the air\'s temperature, the underside on a wire shelf (its vapour to the air by the analogy) or on a solid one at the air\'s temperature; at the stack\'s edges the air\'s vapour pressure. Linear elements with the flows integrated at the nodes (they never overshoot, however thin the pieces), the storage at the nodes, BDF2 in time (second order, its balance exact step by step), Newton on the storage each step with its first factors reused. Each followed piece\'s stress as the Results step\'s (held flat, free in its plane, its natural stretch and stiffness its water\'s, creeping at a rate going as its water): 3D plane stress in its plane, 2D along its edge. 1D: through the stack at its middle; 2D: a section from its middle to an edge; 3D: a quarter.', lim: 'Checked (mp-core.validate.js, stack-mp.validate.js): at the air\'s temperature all through, the water is the Results step\'s (3D mean within 2 %, the 2D strip\'s profile within 0.0003 kg/kg; converged, the same to 0.06 % against an independent explicit solve); with the sides sealed and insulated the 2D and 3D are the 1D (10⁻¹¹); the heat in = the enthalpy\'s rise and the water out = the water lost, each dimension (10⁻¹¹); even water and heat, no stress; the air\'s correlations; BDF2 second order. Set on the inputs bar and Materials: the plate\'s thickness (37.8 mm, from your 1 kPa), the oven\'s air (still), what the stack stands on (a wire shelf), the plate\'s emissivity, GO\'s conductivity along a piece. The stack goes in at the room\'s temperature; the pieces touch perfectly (no contact resistance).' },
  { t: 'The furnace\'s multiphysics (MP-2)', d: 'The furnace\'s stack solved in 1D, 2D or 3D with its heat, its chemistry, its gas and its stress together (furnace-mp.js on mp-core.js). The holder: the pieces and their graphite papers as layers combined (along them in parallel, through them in series with a contact resistance at each face), the isostatic graphite plates above and below; graphite\'s heat capacity with temperature (Butland and Maddison). The hot zone at the program\'s temperature radiates to its faces, the argon takes heat by natural convection; between the runs the stack cools to the room. At every point furnace.js\'s chemistry at its own temperature, and its heat back into the heat: the labile oxygen\'s exotherm (GO\'s DSC: about 1.6 kJ/g) and the water\'s latent heat -- by Newton at the nodes, so a runaway is followed (in shorter steps). Each piece\'s gas along its paper (Darcy, the paper lifting past the load) and across it (G R T h / 8D); each followed piece\'s pull where it converts unevenly, free in its plane. 1D: along the pieces at the stack\'s middle height; 2D: a section through the holder; 3D: a quarter of it.',
    lim: 'Checked (furnace-mp.validate.js): graphite\'s heat capacity; radiation from the hot zone against an independent integration; an isolated stack running away against an independent integration (first order in the step); the chemistry at the program\'s temperature against furnace.js\'s exactly; the layers combined against every piece and paper resolved; the 2D with no plates against the 1D, the 3D with a side sealed against the 2D; the gas under a paper against the obstacle problem\'s exact solution; the heat balance through both runs. Set on Materials and the inputs bar: the GO\'s heat, the papers\' and the plates\' conduction, the contact, the holder\'s emissivity; the hot zone at the program\'s temperature (where is the thermocouple?).' },
  { t: 'The furnace and the graphene film', d: 'The pieces go into the furnace one between each two graphite papers (bigger than them), the stack in a graphite holder, and are heated in argon twice (furnace.js). The film\'s chemistry: its water and its oxygen in three stages (labile, stable, the last with the hydrogen), each first order with a Gaussian spread of activation energies (a distributed activation energy model), their energies from where they peak heated at 10 °C/min (Kissinger\'s condition, a prefactor of 10¹³ /s), integrated exactly over each straight piece of the program (the temperature integral, through the exponential integral); what each leaves as (CO₂, CO, water, H₂) from its shares: the weight, C/O and the gas it makes. Graphitizing alike: the layers\' spacing from 0.344 to 0.3354 nm, the crystallites La growing geometrically between their two sizes. The piece\'s own thickness goes as its layers\' spacing (the water and oxygen out, then graphitizing). The gas gets out through the piece by Knudsen diffusion in the galleries between its layers (a diffusivity going as the square of their opening, down to a floor through its defects, and as the root of the temperature: at the middle the gas is G R T h / (8 D) above the faces), then along the graphite paper to its edges (∇·(κ ∇p) + G = 0 on a quarter, finite volumes, the paper lifting where the gas under it beats the load: an obstacle problem by active sets). Where the gas in the middle beats the layers\' hold (their cohesion and the load on them) they part: the gas held there at the hold, its volume the piece\'s growth (kept), its way out growing with the opening. With the holder\'s plates on the stack, the papers give as the stack grows and the load rises. The heat along the graphene film: graphite\'s times its density over graphite\'s times La / (La + ℓ). Along itself (GO-5b): it shrinks as its water and oxygen leave and it graphitizes (the Furnace card); its paper holds it back, by friction (μ times the load pressing it: the papers\' and the resting plate\'s weight, the papers pushed once the stack fills the gap), or by its bond once stuck (from a temperature set, where pressed). Computed on a disc of the piece\'s area in rings (axisymmetric plane stress, each ring on a spring that slips beyond its limit; Newton on the active set), its stiffness and strength falling with its density as it puffs: it cracks where its pull beats its strength (stuck, into cells 2 σc h / τb apart: a grid), waves where its squeeze beats what buckles it between its papers (2 √(D k) / h). Held by both papers, below and above it (GO-7): their friction and its bond on both faces, so stuck and cracked its cells are 2 σc h / (2 τb) apart. The stack\'s top, middle and bottom pieces go through together: the chemistry and the temperatures theirs alike, each under its own load (the plate, the papers and the pieces above it, as they are then), each with its own gas, paper and hold, the stack\'s growth against the holder theirs together; the batch\'s thickness and spread from them by Simpson\'s rule over the stack. With the load\'s temperature spread given, its coldest and hottest stacks too (each run\'s rise above the room in proportion, the top half the spread off), the batch over the stacks spread evenly between them. A piece sticks where it is pressed at least the Furnace card\'s pressure once hot enough (GO-7c: your waved top pieces come off free, your cracked bottom ones stuck): each ring\'s most pressure once hot is kept, so where in the stack yours stick (Measured) gives the pressure (any between that piece\'s and the one above\'s). With the stack filling its room the holder squeezes every piece alike and none can stick where the others do not: warned. The gas in the film\'s openings and under the paper are solved together each step (each opening\'s exchange linear in the paper\'s gas, Newton for one parting; both backward Euler, meeting where it starts to part), and the holder\'s squeeze from the step\'s end. furnace.validate.js checks the rings against the exact disc.',
    lim: 'Checked (furnace.validate.js): the exponential integral against its tables; the temperature integral against Simpson; one activation energy peaking where set; held at a temperature, 1 − e^(−kt); a spread of energies against its fine integral; the chemistry\'s balances; the gas made = out + held, and = the stages\'; across the film G R T h / (8 D) against a finite-difference solve; the paper\'s square against its exact series, converging; the paper lifting (the obstacle problem\'s conditions); a piece puffing at one temperature against its ODE; the steps converged. Not first principles: the stages, the gas-tightness and the hold are set or fitted (the least gas-tightness that keeps the first run from puffing, Q101; the growth that gives 125 µm from 90 µm, Q95/Q99) until your measured thickness and runs give them; the heat conduction is a correlation. One temperature through each stack (you find its top and bottom about the same); its top, middle and bottom pieces followed. The top and bottom pieces touch the holder\'s isostatic graphite plates (you): their gas out through the plate (its permeability coefficient, the plates\' thickness) or lifting the piece off it, and through their paper; the plate\'s friction, sticking and bond; a wave only into their paper; the pieces next to them followed too (the batch: each end piece one of N, the pieces between by Simpson). The papers give in proportion to the load: jammed past their thickness, beyond this model (warned). Along itself: a disc of the piece\'s area (not its square\'s corners); its shrinking, friction, sticking temperature and bond are set from your sizes after the furnace and your photos; the pieces stay in their stack between the runs; its film is elastic (no creep at the furnace\'s heat). The rings checked against the exact disc (slipping under uniform friction, converging; stuck, exactly); its size free and when it sticks, through the runs; the same piece twice is the piece, each carries the load above it; the batch\'s spread; held on both faces, the cells half as wide; the load\'s stacks; sticking needs pressure (at 0 as before; the top free and the bottom stuck between their weights; a filled room pressing all alike); the film\'s openings and the paper\'s gas solved together (200 pieces squeezed: never below a vacuum -- taken one after the other it blew up to −10¹⁵ Pa -- and converging with the step); the ends against the plates (on papers as before; a sealed plate the one-sided slab; open plates as open papers; the loads with N − 1 papers; converging with the step); the piece along itself balanced at every step (a step that does not lower its energy halved: before, some steps stopped unbalanced). Not known: how the stacks of a load differ (the furnace\'s temperature across it), until you give it.' },
  { t: 'A piece of the film in 3D', d: 'A piece cut from the roll as a thin plate (von Kármán: large deflection, moderate slopes) that wants to curl as the settled film does (film.js\'s layers) both ways, plus along the line the share of the roll\'s bend the roll set; its stiffnesses about its neutral plane; free, or on a table under its weight (the table pushing back where it touches). Bicubic Hermite finite elements (Bogner–Fox–Schmit) on a quarter of the piece with its two mirror lines; the energy minimised by Newton with a Levenberg–Marquardt shift and a line search, the curvature raised in steps. A large piece cannot keep a bowl without stretching and rolls one way: the roll\'s set picks along the line (with none, a tiny preference along the line). Its size pressed flat: on the roll its water evens out through it but stays in; dried through in the pre heat treatment (its air the room\'s heated) it keeps the isotherm\'s water there.',
    lim: 'Checked (sheet.validate.js): the element reproduces a bicubic; the gradient and stiffness against finite differences; one-way curvature gives an exact cylinder; a small piece a spherical cap; a large piece a tube whose curvature tends to (1 + ν) κ̄; the shape scales with κ̄L²/h; a heavy strip on a table against its closed forms (0.2 %); the mesh converged (0.01 %). Not in: steep curls (the model holds for moderate slopes: a warning says when it is past them), a piece rolling so far it touches itself, the flakes\' alignment making the film stiffer one way, how long the roll is kept; how far 1–2 h in the pressed stack dries it, and the wrinkles and waviness it comes out with (next).' },
  { t: 'Structure (thixotropy)', d: 'The slurry\'s structure λ (0 broken down, 1 built up) follows dλ/dt = (1 − λ)/t_b − λ γ̇/(γ̇c t_b): broken down by shear, rebuilt at rest. The stress keeps the steady flow curve: τ = τy (1 + c_y λ)/(1 + c_y λe) + (τe − τy)(1 + c_η λ)/(1 + c_η λe), λe = 1/(1 + γ̇/γ̇c). The 2D carries λ along each streamline of its flow and solves the flow again with it until both settle; the 1D carries it along 64 streamlines of the blade; after the blade it rebuilds at rest on the web, so the ripple levels until the rebuilding yield stress holds it, and the edge bead grows until it does (Film surface, Web edge and 1D To the oven). The 3D uses the steady curve.',
    lim: 'Its values are fitted to a thixotropy test; a single test pins the rebuild time and the gain down better than the shear rate that halves the structure. The 1D and the quick tabs take the representative flow (the 1D the lubrication flow, the quick tabs the shear rate U / H).' },
  { t: 'Film levelling', d: 'Ripple of the chosen wavelength levelled by surface tension and gravity against viscosity (a thin-film levelling time constant 3 μ / (h³ (γ k⁴ + ρ g k²))); a yield stress leaves a residual amplitude it cannot level. The starting ripple is the gap waviness times dh/dH plus vibration.',
    lim: 'Linear, one wavelength at a time; an order-of-magnitude indicator.' },
  { t: 'Start-up animation', d: 'The pool depth from a volume balance (pulsed feed in, gap flow out), the gap flow from the web speed and a bead pressure taken as proportional to pool depth; the downstream surface from the thin-film equation (viscous flow, surface tension, the moving fibre), solved live.',
    lim: 'The start-up, pool depth and length are fixed values. When the pool cannot supply the outlet, the outlet is supply-limited; a numerical failure stops the surface and is reported.' },
  { t: 'CFD', d: 'Steady 2D incompressible Navier–Stokes by finite elements (Taylor–Hood: quadratic velocity, linear pressure) with the viscosity varying as the rheology model says (Newtonian, power law, Herschel–Bulkley). Velocity, pressure, the free surface and the contact line are solved together by Newton\'s method, stepping from a Newtonian fluid to the real rheology. The contact line is pinned at the edge or climbs the exit face (Gibbs). The fibre is porous (Darcy, from its test report). Validated against exact flat-gap flows, the lid-driven cavity, the static meniscus, mass conservation and grid convergence (Coating › 2D › More › Method).',
    lim: 'Steady and 2D (no instabilities along the web). The solver needs exit face + contact angle between 94° and 175°. The contact line position depends on the mesh more than the film does: check with the mesh study. A run that does not converge is not shown.' },
  { t: 'Input checks', d: 'A typed value outside an input\'s range is refused. Before a run, the geometry is checked: errors (outside what the solver can do) stop the run, warnings (outside where the model is valid, or unusual process values) do not. All are listed in the Problems tab.', lim: '' },
  { t: 'DOE', d: 'Full factorial: every combination of the factor levels is one CFD run at the chosen location; the others stay as the base case. Main effects average each level over the other factors.', lim: 'A run with an input outside what the solver can do is not solved; a run that does not converge is marked failed.' },
  { t: 'Measured data and the fit', d: 'Each measured point is predicted by the model (the solved answers: the most detailed model solved; the 1D at a point\'s own settings) and, on request, the CFD (each different point solved once). Error = (predicted − measured) / measured. The fit minimises the RMS % error of the 1D over the chosen datasets in each input\'s range: the 1D at a 3-level design over a box about the current values (5 levels for one input), a quadratic fitted to each point\'s value, its best found, the box halved about it, three times; then the 1D itself at the best; then the fitted values solved in the CFD to check them.',
    lim: 'The 1D and the CFD differ (1D against 2D): a fit on the 1D is a starting point, which the CFD check confirms or not. A fitted value at the end of its range means the best fit may lie beyond it.' },
];

// ---- search: every help text as items ----
function helpItems() {
  const items = [];
  for (const key of Object.keys(HELP)) {
    const h = helpOf(key);
    if (!h) continue;
    const kind = key.startsWith('in.') ? 'Input' : /^(cfd|sol|loc)\./.test(key) ? 'CFD setting' : /^(tb|zm|dp)\./.test(key) ? 'Control' : key.startsWith('doe.') ? 'DOE' : key.startsWith('meas.') ? 'Measured data' : 'Help';
    const id = key.startsWith('in.') ? 'n_' + key.slice(3) : Object.keys(HELP_BY_ID).find(k => HELP_BY_ID[k] === key) || null;
    items.push({ kind, t: h.t, parts: [h.d, h.r, h.e ? `Effect: ${h.e}` : '', h.u ? `Used by: ${h.u}` : ''].filter(Boolean), jump: id });
  }
  for (const [name, d] of Object.entries(HELP_RESULTS)) items.push({ kind: 'Result', t: name, parts: [d] });
  for (const g of GUIDE) items.push({ kind: 'Module', t: g.t, parts: [g.what, `Uses: ${g.uses}`, `Reading it: ${g.read}`], tab: g.tab });
  for (const m of METHODS) items.push({ kind: 'Method', t: m.t, parts: [m.d, m.lim ? `Limits: ${m.lim}` : ''].filter(Boolean) });
  for (const a of KEY_ACTIONS) items.push({ kind: 'Shortcut', t: a.l, parts: [keyOf(a.id) ? `Key: ${keyLabel(a.id)}` : 'No key (set one in Keyboard shortcuts)', a.g], key: true });
  return items;
}
const gEsc = t => String(t ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const stripTags = t => String(t ?? '').replace(/<[^>]*>/g, '');
/** Text with the query's words marked. */
function gMark(text, words) {
  let s = gEsc(stripTags(text));
  for (const w of words) if (w) s = s.replace(new RegExp(`(${w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi'), '<mark>$1</mark>');
  return s;
}

// ---- the dialog ----
const HELPDLG = { sec: 'guide', mod: 0, q: '' };
function openHelp(sec) {
  let dlg = document.getElementById('helpDlg');
  if (!dlg) {
    dlg = document.createElement('dialog'); dlg.id = 'helpDlg'; dlg.className = 'img-dlg help-dlg'; dlg.setAttribute('aria-labelledby', 'helpDlgH');
    document.body.appendChild(dlg);
  }
  HELPDLG.sec = sec || 'guide'; HELPDLG.mod = tab; HELPDLG.q = '';
  dlg.innerHTML = `<div class="help-top"><h2 id="helpDlgH">Help</h2>
      <input type="search" id="helpQ" placeholder="Search help: inputs, results, controls, methods, keys" aria-label="Search help" autocomplete="off">
      <button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
    <div class="help-main"><nav class="help-nav" aria-label="Help sections"></nav><div class="help-body" id="helpBody" tabindex="-1"></div></div>
    <p class="help-foot">${PROJ_APP} ${APP_VERSION} · The ⓘ next to an input, or a moment's hover on a control, shows its card.</p>`;
  dlg.querySelector('[data-close]').onclick = () => dlg.close();
  const q = dlg.querySelector('#helpQ');
  q.oninput = () => { HELPDLG.q = q.value.trim(); renderHelpDlg(); };
  if (!dlg.open) dlg.showModal();
  renderHelpDlg();
  (sec === 'search' ? q : dlg.querySelector('.help-nav [aria-current="page"]') || q).focus();
}
function renderHelpDlg() {
  const dlg = document.getElementById('helpDlg');
  if (!dlg) return;
  const nav = dlg.querySelector('.help-nav'), body = dlg.querySelector('#helpBody'), searching = !!HELPDLG.q;
  const navBtn = (sec, mod, label, sub) => `<button type="button" class="help-nb${sub ? ' sub' : ''}" data-sec="${sec}"${mod != null ? ` data-mod="${mod}"` : ''}${!searching && HELPDLG.sec === sec && (mod == null || HELPDLG.mod === mod) ? ' aria-current="page"' : ''}>${label}</button>`;
  nav.innerHTML = navBtn('guide', null, 'Module guide') + GUIDE.map(g => navBtn('guide', g.tab, g.t + (g.tab === tab ? ' <small>(this one)</small>' : ''), true)).join('')
    + navBtn('methods', null, 'Methods and limits') + navBtn('keys', null, 'Keyboard shortcuts');
  nav.querySelectorAll('[data-sec]').forEach(b => {
    b.onclick = () => {
      HELPDLG.sec = b.dataset.sec; if (b.dataset.mod != null) HELPDLG.mod = +b.dataset.mod;
      HELPDLG.q = ''; dlg.querySelector('#helpQ').value = '';
      renderHelpDlg(); body.scrollTop = 0;
    };
  });
  if (searching) {
    const words = HELPDLG.q.toLowerCase().split(/\s+/).filter(Boolean);
    const scored = helpItems().map(it => {
      const title = it.t.toLowerCase(), text = (it.t + ' ' + it.parts.join(' ')).toLowerCase();
      if (!words.every(w => text.includes(w))) return null;
      return { it, s: words.reduce((a, w) => a + (title.includes(w) ? 3 : 0) + (title.startsWith(w) ? 2 : 0), 0) };
    }).filter(Boolean).sort((a, b) => b.s - a.s);
    body.innerHTML = `<p class="fv-note">${scored.length} result${scored.length === 1 ? '' : 's'} for “${gEsc(HELPDLG.q)}”</p>` + (scored.length ? scored.slice(0, 60).map(({ it }, n) => `<article class="help-hit">
        <div class="help-hit-h"><span class="help-kind">${it.kind}</span><b>${gMark(it.t, words)}</b>${it.jump && document.getElementById(it.jump) ? ` <button type="button" class="btn btn-secondary btn-sm" data-jump="${it.jump}">Show</button>` : ''}${it.tab != null ? ` <button type="button" class="btn btn-secondary btn-sm" data-guide="${it.tab}">Guide</button>` : ''}${it.key ? ` <button type="button" class="btn btn-secondary btn-sm" data-sec2="keys">Change</button>` : ''}</div>
        ${it.parts.map(p => `<p>${gMark(p, words)}</p>`).join('')}</article>`).join('') : '<p class="cap">Nothing found. Try another word (an input\'s name, a result, "contact line", "yield", "mesh"…).</p>');
    body.querySelectorAll('[data-jump]').forEach(b => { b.onclick = () => { dlg.close(); jumpToField(b.dataset.jump); }; });
    body.querySelectorAll('[data-guide]').forEach(b => { b.onclick = () => { HELPDLG.q = ''; dlg.querySelector('#helpQ').value = ''; HELPDLG.sec = 'guide'; HELPDLG.mod = +b.dataset.guide; renderHelpDlg(); }; });
    body.querySelectorAll('[data-sec2]').forEach(b => { b.onclick = () => { HELPDLG.q = ''; dlg.querySelector('#helpQ').value = ''; HELPDLG.sec = 'keys'; renderHelpDlg(); }; });
    return;
  }
  if (HELPDLG.sec === 'guide') {
    const g = GUIDE.find(x => x.tab === HELPDLG.mod) || GUIDE[0];
    body.innerHTML = `<h3 class="help-h">${g.t}${g.tab === tab ? ' <small>the tab shown</small>' : ` <button type="button" class="btn btn-secondary btn-sm" data-go="${g.tab}">Go to this tab</button>`}</h3>
      <p class="help-q">${TAB_Q[g.tab]}</p>
      <h4>What it does</h4><p>${g.what}</p><h4>Inputs it uses</h4><p>${g.uses}</p><h4>Reading it</h4><p>${g.read}</p>${g.more ? `<h4>How it works</h4><p>${g.more}</p>` : ''}
      <h4>Keys</h4><p>${[['run.run', 'run'], ['run.stop', 'stop']].filter(([k]) => keyOf(k) && g.tab >= 4 && g.tab < 12).map(([k, l]) => `<kbd>${keyLabel(k)}</kbd> ${l}`).join(' · ') || ''}${g.tab === 4 ? ` · <kbd>${keyLabel('view.fit')}</kbd> fit, <kbd>${keyLabel('view.l1')}</kbd>…<kbd>${keyLabel('view.l4')}</kbd> location, <kbd>${keyLabel('view.compare')}</kbd> compare, <kbd>${keyLabel('view.diff')}</kbd> difference` : ''}${g.tab < 4 ? 'The panel and edit keys work here (see Keyboard shortcuts).' : ''}</p>`;
    const go = body.querySelector('[data-go]');
    if (go) go.onclick = () => { dlg.close(); tab = +go.dataset.go; render(); };
  } else if (HELPDLG.sec === 'methods') {
    body.innerHTML = `<h3 class="help-h">Methods and limits</h3><p class="fv-note">What each result rests on, and where it stops being reliable.</p>`
      + METHODS.map(m => `<section class="help-m"><h4>${m.t}</h4><p>${m.d}</p>${m.lim ? `<p class="help-lim"><b>Limits.</b> ${m.lim}</p>` : ''}</section>`).join('');
  } else if (HELPDLG.sec === 'keys') {
    body.innerHTML = `<h3 class="help-h">Keyboard shortcuts</h3><p class="fv-note">The menu bar: F10, then the arrows, Enter, Esc. Every command by name: ${keyLabel('tools.palette') || 'Tools › Command palette'}.
      Right-click the 2D flow plots, the 2D steps' drawings or the 3D view for the commands there.</p><div id="helpKeys"></div>`;
    renderKeyEditor(body.querySelector('#helpKeys'));
  }
}
(function helpMenu() {
  const menu = document.getElementById('helpMenu');
  if (!menu) return;
  const w = document.getElementById('hmWelcome'); if (w) w.onclick = () => { menu.open = false; openWelcome(); };
  menu.querySelectorAll('[data-help-sec]').forEach(b => { b.onclick = () => { menu.open = false; openHelp(b.dataset.helpSec); }; });
})();
